	\lim_{s\to 0^+}\Big[\phi(s)^{\frac{\gamma-1}{2-2\mu}}\sqrt{\ell^2+\int_{g(\phi(s))}^{+\infty}f(\xi)d\xi}\Big]^{\frac{2-2\mu}{1+\gamma-2\mu}}    \\
	&=\Big(\frac{1+\gamma-2\mu}{2-2\mu}\Big)^{\frac{2-2\mu}{1+\gamma-2\mu}}
		\lim_{s\to 0^+}\left(\frac{\ell^2+\int_{g(\phi(s))}^{+\infty}f(\xi)d\xi}{ \phi(s)^{\frac{1-\gamma}{1-\mu}} }\right)^{\frac{1-\mu}{1+\gamma-2\mu}}   \\
		&=\Big(\frac{1+\gamma-2\mu}{2-2\mu}\Big)^{\frac{2-2\mu}{1+\gamma-2\mu}}
			\lim_{s\to 0^+}\left(\frac{\int_{g(s)}^{+\infty}f(\xi)d\xi}{s^{\frac{1-\gamma}{1-\mu}} }\right)^{\frac{1-\mu}{1+\gamma-2\mu}}  \\
			\noalign{\vskip4pt}
		&=\Big(\frac{1+\gamma-2\mu}{2-2\mu}\Big)^{\frac{2-2\mu}{1+\gamma-2\mu}}		
f_0^{\frac{1-\mu}{1+\gamma-2\mu}} a_0^{\frac{\gamma-1}{2(1+\gamma-2\mu)}}(\gamma-1)^{\frac{\mu-1}{1+\gamma-2\mu}} 
			(1-\mu)^{\frac{1-\gamma}{1+\gamma-2\mu}}.
	\end{align*}
We are now ready to conclude the proof 
of Theorem~\ref{main}. 
In light of \cite[Theorem 1.1]{craRabTar}, since $h(s)\to +\infty$ as $s\to 0^+$ by \eqref{limzze}
and $h$ is non-increasing for $s>0$ by \eqref{ass-fg}, there exists a unique positive solution $z\in C^2(\Omega)\cap C(\bar\Omega)$
to $-\Delta v=h(v)$. Then $g(z)\in C^2(\Omega)\cap C(\bar\Omega)$ is a positive solution to \eqref{prob}. Assume that
$u_1,u_2\in C^2(\Omega)\cap C(\bar\Omega)$, $u_1,u_2>0$ solve \eqref{prob}. Then $g^{-1}(u_1),g^{-1}(u_2)>0$ solve
